SELECT symbol, DATE_FORMAT(observed_at,'%H:%i') AS ksa_minute, COUNT(*) AS events, MIN(price) AS min_price, MAX(price) AS max_price, MIN(observed_at) AS first_obs, MAX(observed_at) AS last_obs FROM market_price_event WHERE symbol IN ('AEROUSDT','UNIUSDT') AND observed_at BETWEEN '2026-10-10 17:56:00' AND '2026-10-10 18:16:00' GROUP BY symbol, ksa_minute ORDER BY symbol, ksa_minute LIMIT 60